INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王令谋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：王令谋。", "biography": null, "status": "draft", "id": "9e5d762a-d3f4-5119-ba0f-3adecd690320"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "张朏", "aliases": ["張朏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋山南东道行军司马。937年奉安从进命率军与复州兵会合，在重要道路阻截安州叛将王晖。", "biography": null, "status": "draft", "id": "3496318c-d7dc-5e10-94bc-8f88c568e35f"}, {"name": "王晖（安州威和指挥使）", "aliases": ["王暉（安州威和指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋安州威和指挥使。937年杀死安远节度使周瑰，自行掌管军府，准备根据范延光胜败决定依附或逃往吴国。", "biography": null, "status": "draft", "id": "45a72072-bb39-5411-99db-123a3029fbc5"}, {"name": "胡进", "aliases": ["胡進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安州将领，王晖的部将。937年在王晖准备逃往吴国时将他杀死。", "biography": null, "status": "draft", "id": "2de353b3-e484-5ded-a646-c80e2448e244"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "武彦和", "aliases": ["武彥和"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "后晋安州指挥使。937年参与安州军乱后，因携带大量财物被李金全设伏捕杀。他临死时质问为何首恶获赦而胁从被杀。", "biography": null, "status": "draft", "id": "54e7495e-1d96-59a6-b058-e0aff73ff602"}, {"name": "杨濛", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨濛。", "biography": null, "status": "draft", "id": "5df06457-f39c-5b71-8a81-1ed0df31c2cc"}, {"name": "王宏", "aliases": ["王宏（吴控鹤军使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王宏，奉命带二百兵看守者。", "biography": null, "status": "draft", "id": "215d8e62-0ff7-5b9f-9e9c-755172175951"}, {"name": "王氏（守卫军使王宏之子）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "吴国守卫军使王宏的儿子，姓名未记。937年父亲被杨濛杀死后，他率兵进攻杨濛，被杨濛射杀。", "biography": null, "status": "draft", "id": "d11d9944-bc8f-57cc-9477-2199d51cf7ad"}, {"name": "周本", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：周本。", "biography": null, "status": "draft", "id": "88dc9c09-49c3-51ee-b872-381abedabdf2"}, {"name": "周弘祚", "aliases": ["弘祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：周弘祚，逼父参加者。", "biography": null, "status": "draft", "id": "0d21f338-4373-5881-a9a5-3b4d4311ff0f"}, {"name": "郭悰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国侍卫军使。937年在和州杀死杨濛的妻子儿女，随后被徐诰归责，贬往池州。", "biography": null, "status": "draft", "id": "4cec8b03-96a0-5541-92c5-72ce65618183"}, {"name": "张从宾", "aliases": ["張從賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张从宾，侍卫步军都指挥使、忠正节度使。", "biography": null, "status": "draft", "id": "9a3c8e19-d709-5a20-b9dd-ef00849d161d"}, {"name": "符彦饶", "aliases": ["符彥饒", "李彦饶", "李彥饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦饶，被逼为帅、要求停止焚掠者。", "biography": null, "status": "draft", "id": "fab16ea8-291a-5d04-86b9-d463c9d60303"}, {"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "李德诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：李德诚。", "biography": null, "status": "draft", "id": "59a78323-0271-515f-9eee-806a51a30252"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "娄继英", "aliases": ["婁繼英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光二年条所见人物：娄继英。", "biography": null, "status": "draft", "id": "f6c6be57-cfd2-54e0-a3d3-f6de4e943c92"}, {"name": "安崇阮", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安崇阮，宁江节度使、弃镇逃归者。", "biography": null, "status": "draft", "id": "a538457e-567c-5c8f-90bc-2f3a4a5cc961"}, {"name": "郭氏（朱友贞妃）", "aliases": ["誓正"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后梁末帝朱友贞的妃子。937年与安崇阮被命收葬朱友贞首级。《新五代史》记她的父亲郭归厚曾任登州刺史，她在梁亡后出家，法名誓正，居洛阳。", "biography": null, "status": "draft", "id": "2059d7c3-b92e-5091-bd33-12705490e853"}, {"name": "朱友贞", "aliases": ["朱锽", "朱瑱", "均王", "梁末帝"], "era": "五代十国", "birth_year": null, "death_year": 923, "description": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "biography": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "status": "draft", "id": "592627e4-8841-5cca-a79b-782c37765037"}, {"name": "郭归厚", "aliases": ["郭歸厚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后梁官员，曾任登州刺史，是末帝次妃郭氏的父亲。具体生卒年份尚未记明。", "biography": null, "status": "draft", "id": "5d601c05-cfd3-5c4e-9fc9-773ab8120fab"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

